def canon_name(value):
    """Validate and canonicalise an absolute domain name."""
    if type(value) is not str:
        fail()
    if value == '.':
        return '.'
    if not value.endswith('.'):
        fail()
    body = value[:-1]
    if body == '':
        fail()
    labels = body.split('.')
    wire = 1
    for label in labels:
        if label == '*':
            wire += 2
        elif LABEL_RE.fullmatch(label):
            wire += 1 + len(label)
        else:
            fail()
    if wire > MAX_WIRE:
        fail()
    return '.'.join(label.lower() for label in labels) + '.'


def canon_data(rtype, value):
    """Validate and canonicalise record data for the given type."""
    if type(value) is not str:
        fail()
    if rtype == 'A':
        parts = value.split('.')
        if len(parts) != 4:
            fail()
        for part in parts:
            if not OCTET_RE.fullmatch(part):
                fail()
            if int(part) > 255:
                fail()
        return value
    if rtype == 'AAAA':
        if '%' in value:
            fail()
        try:
            addr = ipaddress.IPv6Address(value)
        except ValueError:
            fail()
        return addr.compressed
    if rtype == 'TXT':
        if len(value) > MAX_TXT:
            fail()
        for char in value:
            code = ord(char)
            if code < 0x20 or code > 0x7E:
                fail()
        return value
    # CNAME
    return canon_name(value)


def canon_record(record):
    require_keys(record, ('owner', 'type', 'data'))
    rtype = record['type']
    if type(rtype) is not str or rtype not in TYPES:
        fail()
    owner = canon_name(record['owner'])
    data = canon_data(rtype, record['data'])
    return (owner, rtype, data)


def label_count(name):
    if name == '.':
        return 0
    return name.count('.')


def labels_of(name):
    if name == '.':
        return []
    return name[:-1].split('.')


def name_of_labels(labels):
    if not labels:
        return '.'
    return '.'.join(labels) + '.'


def parent_name(name):
    if name == '.':
        return '.'
    index = name.find('.')
    if index < 0:
        return '.'
    rest = name[index + 1:]
    return rest if rest else '.'


def at_or_below(name, origin):
    """True when name is the origin itself or a descendant of it."""
    if origin == '.':
        return True
    if name == origin:
        return True
    return name.endswith('.' + origin)


